local pumps = script.Parent.Functional;

local function findVehicleInRange(pump)
	for each, vehicle in pairs(workspace.Vehicles:GetChildren()) do
		if (vehicle.Functional.FuelCap.Position - pump.HoseAnchor.Position).Magnitude <= pump.Handle.RopeConstraint.Length then
			for each, otherPump in pairs(pumps:GetChildren()) do
				if otherPump.Handle.WeldConstraint.Part1 == vehicle.Functional.FuelCap then
					return nil;
				end
			end
			return vehicle;
		end
	end
end

local function weldPump(handle, nozzle, target)
	handle.WeldConstraint.Enabled = false;
	handle.WeldConstraint.Part1 = target;
	nozzle.CFrame = target.CFrame;
	handle.WeldConstraint.Enabled = true;
end

for each, pump in pairs(pumps:GetChildren()) do
	local handle = pump.Handle;
	local nozzle = pump.Nozzle;
	local sign = pump.Sign;
	local vehicle;

	sign.SurfaceGui.Type.Text = pump:GetAttribute("Pump_Type");
	sign.SurfaceGui.Cost.Text = string.format("$%.2f", pump:GetAttribute("Pump_Cost")).." / "..pump:GetAttribute("Pump_Amount").." units";
	sign.SurfaceGui.Pumped.Text = "";

	handle.ProximityPrompt.Triggered:Connect(function(player)
		if not pump:GetAttribute("Pump_Connected") then
			vehicle = findVehicleInRange(pump);
			if vehicle then
				pump:SetAttribute("Pump_Connected", true);
				handle.ProximityPrompt.ActionText = "Unhook from vehicle";
				weldPump(handle, nozzle, vehicle.Functional.FuelCap);
			end
		elseif pump:GetAttribute("Pump_Connected") then
			pump:SetAttribute("Pump_Connected", false);
			handle.ProximityPrompt.ActionText = "Hook to vehicle";
			weldPump(handle, nozzle, pump.HandleStorage);
		end
	end)

	pump:GetAttributeChangedSignal("Pump_Connected"):Connect(function()
		if pump:GetAttribute("Pump_Connected") then
			nozzle.Fill:Play();
			vehicle:SetAttribute("Car_Fueling", true);
			vehicle:SetAttribute("Car_Running", false);

			local moneySpent = 0;			
			while pump:GetAttribute("Pump_Connected") and vehicle:GetAttribute("Fuel_Current") < vehicle:GetAttribute("Fuel_Max") do
				if vehicle:GetAttribute("Fuel_Efficiency") ~= pump:GetAttribute("Pump_Efficiency") then
					vehicle:SetAttribute("Fuel_Efficiency", pump:GetAttribute("Pump_Efficiency"));
					vehicle:SetAttribute("Fuel_Current", 0);
				end

				vehicle:SetAttribute("Fuel_Current", vehicle:GetAttribute("Fuel_Current") + (pump:GetAttribute("Pump_Amount") / 10));
				if vehicle:GetAttribute("Fuel_Current") >= vehicle:GetAttribute("Fuel_Max") then
					vehicle:SetAttribute("Fuel_Current", vehicle:GetAttribute("Fuel_Max"));
				end

				moneySpent += pump:GetAttribute("Pump_Cost") / 10;
				sign.SurfaceGui.Pumped.Text = string.format("$%.2f", moneySpent);
				task.wait(0.1);
			end

			nozzle.Fill:Stop();
			vehicle:SetAttribute("Car_Fueling", false);
		end
	end)
end

