local TweenService = game:GetService("TweenService");
local group = script.Parent;
local signals = group:WaitForChild("Signals");
local boomarms = group:WaitForChild("Boomarms");
local sensors = group:WaitForChild("Sensors");
local lightTweenInfo = TweenInfo.new(group:GetAttribute("LightSpeed"));
local boomarmTweenInfo = TweenInfo.new(group:GetAttribute("TimeToDropBoomarm"), Enum.EasingStyle.Sine);
local raisedTween;

local function toggleLight(light, toggle)
	local lightVisualTween;
	local lightEffectTween;

	if toggle then
		lightVisualTween = TweenService:Create(light, lightTweenInfo, {Color = Color3.fromRGB(255, 80, 80)});
		lightEffectTween = TweenService:Create(light.PointLight, lightTweenInfo, {Range = 10});
	else
		lightVisualTween = TweenService:Create(light, lightTweenInfo, {Color = Color3.fromRGB(0, 0, 0)});
		lightEffectTween = TweenService:Create(light.PointLight, lightTweenInfo, {Range = 0});
	end

	lightVisualTween:Play();
	lightEffectTween:Play();
end

local function trainIsInSensorBlock()
	for each, sensor in pairs(sensors:GetChildren()) do
		local foundParts = workspace:GetPartsInPart(sensor);
		for each, part in pairs(foundParts) do
			if part:IsDescendantOf(workspace.Trains) then
				return true;
			end
		end
	end
end

local function boomarmIsBlocked(boomarm)
	local foundParts = workspace:GetPartsInPart(boomarm.Functional.BoomarmSensor);
	for each, part in pairs(foundParts) do
		if part:IsDescendantOf(workspace.Vehicles) then
			return true;
		end
	end
end

local function initialize()
	group:SetAttribute("TimeSinceLastActivationChange", os.time());

	for each, boomarm in pairs(boomarms:GetChildren()) do
		for each, part in pairs(boomarm:GetDescendants()) do
			if part:IsA("BasePart") and not part.Anchored and not part:FindFirstChildOfClass("WeldConstraint") then
				part:SetNetworkOwner();
			end
		end
	end
end
initialize();

group:GetAttributeChangedSignal("LightsActivated"):Connect(function()
	while group:GetAttribute("LightsActivated") do
		if group:GetAttribute("LightsActivated") then
			for each, signal in pairs(signals:GetChildren()) do
				for each, light in pairs(signal.Functional.Lights:GetChildren()) do
					toggleLight(light, string.sub(light.Name, 1, 4) == "Left");
				end
			end
			for each, boomarm in pairs(boomarms:GetChildren()) do
				for each, light in pairs(boomarm.Functional.Lights:GetChildren()) do
					toggleLight(light, string.sub(light.Name, 1, 4) == "Left");
				end
			end
			task.wait(group:GetAttribute("LightSpeed"));
		end

		if group:GetAttribute("LightsActivated") then
			for each, signal in pairs(signals:GetChildren()) do
				for each, light in pairs(signal.Functional.Lights:GetChildren()) do
					toggleLight(light, string.sub(light.Name, 1, 5) == "Right");
				end
			end
			for each, boomarm in pairs(boomarms:GetChildren()) do
				for each, light in pairs(boomarm.Functional.Lights:GetChildren()) do
					toggleLight(light, string.sub(light.Name, 1, 5) == "Right");
				end
			end
			task.wait(group:GetAttribute("LightSpeed"));
		end
	end

	for each, signal in pairs(signals:GetChildren()) do
		for each, light in pairs(signal.Functional.Lights:GetChildren()) do
			toggleLight(light, false);
		end
	end
	for each, boomarm in pairs(boomarms:GetChildren()) do
		for each, light in pairs(boomarm.Functional.Lights:GetChildren()) do
			toggleLight(light, false);
		end
	end
end)

group:GetAttributeChangedSignal("SignalActivated"):Connect(function()
	for each, signal in pairs(signals:GetChildren()) do
		if group:GetAttribute("SignalActivated") then
			if not signal.Functional.Soundbox.Crossing.Playing then
				signal.Functional.Soundbox.Crossing:Play();
			end
		else
			signal.Functional.Soundbox.Crossing:Stop();
		end
	end

	if group:GetAttribute("SignalActivated") then
		group:SetAttribute("LightsActivated", true);
		if #boomarms:GetChildren() > 0 then
			task.wait(group:GetAttribute("TimeBeforeBoomarmDrop"));
		end
	end

	if group:GetAttribute("SignalActivated") then
		for each, boomarm in pairs(boomarms:GetChildren()) do
			coroutine.wrap(function()
				local loweredTween = TweenService:Create(boomarm.Functional.Motor, boomarmTweenInfo, {CFrame = boomarm.Functional.Motor.Lowered.CFrame})
				loweredTween:Play();

				while loweredTween.PlaybackState ~= Enum.PlaybackState.Completed do
					if boomarmIsBlocked(boomarm) then
						loweredTween:Pause();
					else
						loweredTween:Play();
					end
					task.wait(0.1);
				end
			end)()
		end
	end

	if not group:GetAttribute("SignalActivated") then
		for each, boomarm in pairs(boomarms:GetChildren()) do
			raisedTween = TweenService:Create(boomarm.Functional.Motor, boomarmTweenInfo, {CFrame = boomarm.Functional.Motor.Raised.CFrame})
			raisedTween:Play();
		end

		if not raisedTween then
			group:SetAttribute("LightsActivated", false);
		else
			raisedTween.Completed:Wait();
			if not group:GetAttribute("SignalActivated") then
				group:SetAttribute("LightsActivated", false);
			end
		end
	end
end)

coroutine.wrap(function()
	while true do
		if trainIsInSensorBlock() and not group:GetAttribute("SignalActivated") then
			if os.time() - group:GetAttribute("TimeSinceLastActivationChange") >= group:GetAttribute("ActivationCooldown") then
				group:SetAttribute("TimeSinceLastActivationChange", os.time());
				group:SetAttribute("SignalActivated", true);
			end
		elseif not trainIsInSensorBlock() and group:GetAttribute("SignalActivated") then
			if os.time() - group:GetAttribute("TimeSinceLastActivationChange") >= group:GetAttribute("ActivationCooldown") then
				group:SetAttribute("TimeSinceLastActivationChange", os.time());
				group:SetAttribute("SignalActivated", false);
			end
		end
		task.wait(group:GetAttribute("ActivationCooldown"));
	end
end)()

