		local rightVector = massPart.CFrame.LookVector:Cross(Vector3.yAxis) * (vehicleSeat.SteerFloat * tiltAngle);
		massPart.AlignOrientation.PrimaryAxis = (Vector3.yAxis + rightVector).Unit;
	end
end)

